let (mut f, temporal) = loop {
    let semilla = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.subsec_nanos())
        .unwrap_or(0)
        ^ (std::process::id() << 8)
        ^ intento;
    let cand = padre.join(format!(".mf-{semilla:08x}.tmp"));
