    // falla ante un enlace simbolico o duro ya plantado en vez de escribir por el.
    match fs::OpenOptions::new().write(true).create_new(true).open(&cand) {
        Ok(f) => break (f, cand),
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists && intento < 8 => {
            intento += 1;
        }
        Err(e) => return Err(format!("No se pudo escribir el temporal: {e}")),
