/// un .md de 64 MB ya no es una nota, y el editor no lo va a sostener.
const TOPE_DOCUMENTO: u64 = 64 * 1024 * 1024;

#[tauri::command]
fn leer(ruta: String) -> Result<Documento, String> {
    let p = PathBuf::from(&ruta);

    let meta = fs::metadata(&p)
        .map_err(|e| format!("No se pudo leer «{}»: {e}", nombre_de(&p)))?;
    if meta.len() > TOPE_DOCUMENTO {
        return Err(format!(
            "«{}» pesa {} MB y no se abre (tope: {} MB)",
            nombre_de(&p),
            meta.len() / 1024 / 1024,
            TOPE_DOCUMENTO / 1024 / 1024
        ));
    }

    let mut crudo = fs::read(&p)
        .map_err(|e| format!("No se pudo leer «{}»: {e}", nombre_de(&p)))?;

    // El BOM se recorta DENTRO del mismo buffer: sin segunda reserva.
    if crudo.starts_with(&[0xEF, 0xBB, 0xBF]) {
        crudo.drain(..3);
    }

    let mut texto = String::from_utf8(crudo).map_err(|_| {
        format!(
            "«{}» no esta en UTF-8. MarkFlow no lo abre para no corromperlo al guardar.",
            nombre_de(&p)
        )
    })?;

    let fin_de_linea = if texto.contains("\r\n") { FinDeLinea::Crlf } else { FinDeLinea::Lf };
    if fin_de_linea == FinDeLinea::Crlf {
        texto = texto.replace("\r\n", "\n");   // solo cuando hace falta
